create extension if not exists pgcrypto;
create type public.transaction_type as enum ('income','expense');
create type public.recurrence_frequency as enum ('once','weekly','biweekly','monthly','yearly');
create type public.balance_anchor_status as enum ('connected','overridden');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.financial_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Personal Cash Flow',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id));
create table public.balance_anchors(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.financial_accounts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,initial_date date not null,initial_balance numeric(14,2) not null,status public.balance_anchor_status not null default 'connected',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(account_id,user_id));
create table public.recurring_transaction_rules(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.financial_accounts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 120),amount numeric(14,2) not null check(amount<>0),transaction_type public.transaction_type not null,start_date date not null,end_date date,frequency public.recurrence_frequency not null,parent_rule_id uuid references public.recurring_transaction_rules(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date is null or end_date>=start_date));
create table public.transactions(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.financial_accounts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,recurring_rule_id uuid references public.recurring_transaction_rules(id) on delete set null,name text not null check(char_length(trim(name)) between 1 and 120),amount numeric(14,2) not null check(amount<>0),transaction_date date not null,sort_order integer not null default 1000,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.saved_calculations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 120),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.calculation_rows(id uuid primary key default gen_random_uuid(),calculation_id uuid not null references public.saved_calculations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null,name text check(name is null or char_length(trim(name))<=120),sort_order integer not null default 1000,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index transactions_account_date_order_idx on public.transactions(account_id,transaction_date,sort_order);
create index transactions_user_idx on public.transactions(user_id);
create index recurring_rules_account_start_idx on public.recurring_transaction_rules(account_id,start_date);
create index calculation_rows_calculation_order_idx on public.calculation_rows(calculation_id,sort_order);

alter table public.profiles enable row level security;alter table public.financial_accounts enable row level security;alter table public.balance_anchors enable row level security;alter table public.recurring_transaction_rules enable row level security;alter table public.transactions enable row level security;alter table public.saved_calculations enable row level security;alter table public.calculation_rows enable row level security;
create policy "profiles own rows" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "accounts own rows" on public.financial_accounts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "anchors own rows" on public.balance_anchors for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "recurring rules own rows" on public.recurring_transaction_rules for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "transactions own rows" on public.transactions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "calculations own rows" on public.saved_calculations for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "calculation rows own rows" on public.calculation_rows for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
